if (envelope.ev.t === 'tool-call-end') {
    return {
        id: messageId,
        localId,
        createdAt: messageCreatedAt,
        role: 'agent',
        isSidechain,
        content: [{
            type: 'tool-result',
            tool_use_id: envelope.ev.call,
            content: envelope.ev.result ?? null,
            is_error: false,
            uuid: contentUUID,
            parentUUID
        }],
        meta
    } satisfies NormalizedMessage;
}
